class ErrorBoundary extends React.Component {
  state = { error: null };

  static getDerivedStateFromError(error) {
    return { error };          // render the fallback
  }

  componentDidCatch(error, info) {
    logToService(error, info); // report it
  }

  render() {
    return this.state.error
      ? this.props.fallback
      : this.props.children;
  }
}

